INSERT INTO questions (source, year, subject, topic, enunciado, opcoes, gabarito, explicacao) VALUES
  ('exam', 2023, 'Economia', NULL, 'Q4 Item 1 (TPS 2023): Considerando os aspectos linguísticos e o sentido do texto, julgue (C ou E) os itens a seguir. | No primeiro parágrafo, “antropólogo pernambucano” (linha 7) e “ele” (linha 10) estabelecem referenciação anafórica com “Gilberto Freyre” (linha 3).', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2023, 'Economia', NULL, 'Q4 Item 2 (TPS 2023): Considerando os aspectos linguísticos e o sentido do texto, julgue (C ou E) os itens a seguir. | A inserção de vírgula após a palavra “cana” (linha 15) manteria a correção gramatical e os sentidos construídos no período.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2023, 'Economia', NULL, 'Q4 Item 3 (TPS 2023): Considerando os aspectos linguísticos e o sentido do texto, julgue (C ou E) os itens a seguir. | A palavra “até” (linha 24) estabelece um sentido de limite em relação aos alojamentos constituídos dentro das senzalas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2023, 'Economia', NULL, 'Q4 Item 4 (TPS 2023): Considerando os aspectos linguísticos e o sentido do texto, julgue (C ou E) os itens a seguir. | Na forma verbal “se determinava” (linha 29), o emprego da partícula “se” marca a indeterminação do sujeito da oração.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2023, 'Economia', NULL, 'Q5 Item 1 (TPS 2023): A respeito dos recursos linguísticos presentes no texto, julgue (C ou E) os itens a seguir. | A substituição de “puros-sangues” (linha 33) por puros-sangue manteria a correção quanto ao emprego de plural desse adjetivo.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2023, 'Economia', NULL, 'Q5 Item 2 (TPS 2023): A respeito dos recursos linguísticos presentes no texto, julgue (C ou E) os itens a seguir. | O trecho “Na medida em que eram considerados pagãos” (linhas 34 e 35) confere ao período em que foi empregado uma relação de causalidade.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2023, 'Economia', NULL, 'Q5 Item 3 (TPS 2023): A respeito dos recursos linguísticos presentes no texto, julgue (C ou E) os itens a seguir. | Nas linhas 39 e 40, o uso de parênteses em “aqueles recém-chegados” e em “aculturados” sinaliza ressalvas quanto ao emprego de determinadas expressões ou palavras no período.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2023, 'Economia', NULL, 'Q5 Item 4 (TPS 2023): A respeito dos recursos linguísticos presentes no texto, julgue (C ou E) os itens a seguir. | A utilização de aspas em “‘nenhuma das anteriores”’ (linha 51) tem função de marcar citação direta no texto. 31 O poeta é um fingidor Finge tão completamente Que chega a fingir que é dor 34 A dor que deveras sente E os que leem o que escreve, 37 Na dor lida sentem bem, Não as duas que ele teve, Mas só a que eles não têm 40 E assim nas calhas de roda Gira, a entreter a razão, 43 Esse comboio de corda Que se chama coração 46 PESSOA, Fernando. Autopsicografia. In: Antologia Poética. Lisboa: Relógio d’água, 2014, p. 50 A respeito dos aspectos linguísticos e semânticos do texto, 49 julgue (C ou E) os itens a seguir. 1 A repetição da palavra “dor” (linhas 3, 4 e 6) constitui a 52 figura de linguagem anáfora.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2023, 'Economia', NULL, 'Q6 Item 1 (TPS 2023): Com base nas ideias apresentadas no texto, julgue (C ou E) os itens a seguir. Não é possível falarmos acerca da elaboração de uma nova história da literatura brasileira e da inserção das | O texto critica a história da literatura brasileira que escritoras mulheres nessa história sem antes entendermos produz inverdades, uma vez que o ponto de vista dos como se dá o processo de construção das histórias e do historiadores é unificado e centralizador, além de cânone literários. O historiador também tem o poder de decorrer de fontes restritas e documentos históricos, o legitimar o escritor e a literatura, pela inclusão e abertura que impossibilita uma escrita que atenda a visões de espaço para análise e consideração de sua obra literária. múltiplas. O contrário também é possível, pois, ao excluir escritores, 2 No segundo parágrafo, o “intercâmbio dialético entre luz acaba silenciando uma produção que gradualmente vai e sombra” (linhas 25 e 26) refere-se a estilos liter', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2023, 'Economia', NULL, 'Q6 Item 2 (TPS 2023): Com base nas ideias apresentadas no texto, julgue (C ou E) os itens a seguir. Não é possível falarmos acerca da elaboração de uma nova história da literatura brasileira e da inserção das | O sentido de “fazer abstração” (linha 5) é o de desconsiderar, reduzir a importância.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2023, 'Economia', NULL, 'Q6 Item 3 (TPS 2023): Com base nas ideias apresentadas no texto, julgue (C ou E) os itens a seguir. Não é possível falarmos acerca da elaboração de uma nova história da literatura brasileira e da inserção das | O autor justifica o próprio voto alinhado ao da maioria dos juízes da CIJ, em favor do desarmamento nuclear.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2023, 'Economia', NULL, 'Q6 Item 4 (TPS 2023): Com base nas ideias apresentadas no texto, julgue (C ou E) os itens a seguir. Não é possível falarmos acerca da elaboração de uma nova história da literatura brasileira e da inserção das | O autor critica a CIJ, o órgão máximo das Nações Unidas, por não ter mostrado sensibilidade diante de uma das maiores preocupações da humanidade.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2023, 'Economia', NULL, 'Q12 Item 1 (TPS 2023): O Mercado Comum do Sul (MERCOSUL) despontou, nos anos de 1990, como dimensão central da estratégia de inserção regional e internacional do Brasil no marco de uma economia mundial organizada em grandes blocos econômicos e crescentemente globalizada. Ao mesmo tempo, pôs em evidência a necessidade de conciliar desígnios políticos domésticos com possibilidades de ação coletiva no plano regional e de lidar com assimetrias políticas e econômicas. A esse respeito, julgue (C ou E) os itens a seguir. | A incorporação do Paraguai e do Uruguai ao MERCOSUL levou à reformulação do objetivo originalmente pactuado bilateralmente pelo Brasil e pela Argentina de estabelecer um mercado comum em favor da instauração de uma área de livre comércio sob a égide de uma união aduaneira como forma de acomodar as discrepâncias econômicas entre os quatro países.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2023, 'Economia', NULL, 'Q12 Item 2 (TPS 2023): O Mercado Comum do Sul (MERCOSUL) despontou, nos anos de 1990, como dimensão central da estratégia de inserção regional e internacional do Brasil no marco de uma economia mundial organizada em grandes blocos econômicos e crescentemente globalizada. Ao mesmo tempo, pôs em evidência a necessidade de conciliar desígnios políticos domésticos com possibilidades de ação coletiva no plano regional e de lidar com assimetrias políticas e econômicas. A esse respeito, julgue (C ou E) os itens a seguir. | Acompanhando a agenda econômica e comercial do MERCOSUL, houve avanços na agenda não econômica, entre outros, nos campos educacional, da seguridade social e da livre circulação de pessoas no interior do bloco.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2023, 'Economia', NULL, 'Q12 Item 3 (TPS 2023): O Mercado Comum do Sul (MERCOSUL) despontou, nos anos de 1990, como dimensão central da estratégia de inserção regional e internacional do Brasil no marco de uma economia mundial organizada em grandes blocos econômicos e crescentemente globalizada. Ao mesmo tempo, pôs em evidência a necessidade de conciliar desígnios políticos domésticos com possibilidades de ação coletiva no plano regional e de lidar com assimetrias políticas e econômicas. A esse respeito, julgue (C ou E) os itens a seguir. | As negociações do Acordo de Associação MERCOSUL – União Europeia, a despeito de seu escopo comercial, têm sido marcadas por dificuldades políticas resultantes de diferentes abordagens e impasses entre as partes acerca de questões extrapauta como defesa, cibersegurança, combate ao terrorismo, proteção dos direitos humanos e desenvolvimento sustentável.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2023, 'Economia', NULL, 'Q12 Item 4 (TPS 2023): O Mercado Comum do Sul (MERCOSUL) despontou, nos anos de 1990, como dimensão central da estratégia de inserção regional e internacional do Brasil no marco de uma economia mundial organizada em grandes blocos econômicos e crescentemente globalizada. Ao mesmo tempo, pôs em evidência a necessidade de conciliar desígnios políticos domésticos com possibilidades de ação coletiva no plano regional e de lidar com assimetrias políticas e econômicas. A esse respeito, julgue (C ou E) os itens a seguir. | O exercício da Presidência pro tempore do MERCOSUL alternadamente pelos países-membros, por período de seis meses, lhes faculta aproximar as respectivas agendas e prioridades domésticas à agenda de bloco. No exercício da Presidência pro tempore do bloco em 2023, o governo brasileiro elegeu, entre suas prioridades, o apoio ao financiamento de infraestrutura física e digital, o revigoramento das instituições do bloco, como Parlamento, o Instituto de Políticas Públicas em Dire', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2023, 'Economia', NULL, 'Q13 Item 1 (TPS 2023): A sociedade brasileira vem presenciando um vigoroso movimento contra o racismo embutido nas estruturas econômicas, sociais, políticas e culturais do Brasil. Esse movimento busca valorizar o componente originário da África na formação identitária do País, o que reforça, entre outros aspectos, a importância das relações entre o Brasil e o continente africano. No que se refere a essas relações, julgue (C ou E) os itens as seguir. PROVA A1 2 3 PAs africanos século 2000 exportados açúcar, agrícolas.  | A cooperação entre o Brasil e os países africanos não se limita ao intercâmbio comercial. Vários acordos de cooperação estão vigentes, sobretudo com países de língua portuguesa, e no seio da CPLP, criada oficialmente no governo de Fernando Henrique Cardoso, em áreas de intercâmbio universitário, cooperação educacional, científica e tecnológica, programas de capacitação profissional, entre outros. Área Livre CONCURSO PÚBLICO TERCEIRO‐SECRETÁRIO DA CARREIRA DE DIPLOMATA T', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2023, 'Economia', NULL, 'Q13 Item 2 (TPS 2023): A sociedade brasileira vem presenciando um vigoroso movimento contra o racismo embutido nas estruturas econômicas, sociais, políticas e culturais do Brasil. Esse movimento busca valorizar o componente originário da África na formação identitária do País, o que reforça, entre outros aspectos, a importância das relações entre o Brasil e o continente africano. No que se refere a essas relações, julgue (C ou E) os itens as seguir. PROVA A1 2 3 PAs africanos século 2000 exportados açúcar, agrícolas.  | Em 2009, a União das Nações Sul-Americanas (Unasul), por iniciativa brasileira, reconheceu as Forças Armadas Revolucionárias da Colômbia (Farc) como grupo narcoterrorista, porém não houve nenhum tipo de intervenção militar por parte da organização, no território colombiano. CONCURSO PÚBLICO TERCEIRO‐SECRETÁRIO DA CARREIRA DE DIPLOMATA TIPO “A” – MANHÃ PÁGINA 10/15 Geografia QUESTÃO 22 Itens de 23 a 28 O Brasil tem se engajado na cooperação sul-sul como prática important', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2023, 'Economia', NULL, 'Q23 Item 1 (TPS 2023): coordenadas pela Agência Brasileira de Cooperação (ABC) e implementadas com a colaboração de vários órgãos federais e organizações parceiras. A prática brasileira da cooperação sul-sul busca se diferenciar, em vários aspectos, da cooperação norte-sul, praticada pelos doadores tradicionais. Acerca desse assunto, julgue (C ou E) os itens seguir. Entende-se sistema urbano como um componente espacial do desenvolvimento social, o resultado de uma evolução histórica. A rede de cidades que o compõe, em | No Brasil e no plano internacional, a cooperação sul-sul já foi chamada de cooperação técnica entre países desenvolvimento, tendo como referência a Primeira Conferência das Nações Unidas sobre Cooperação Técnica entre Países em Desenvolvimento.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2023, 'Economia', NULL, 'Q23 Item 2 (TPS 2023): coordenadas pela Agência Brasileira de Cooperação (ABC) e implementadas com a colaboração de vários órgãos federais e organizações parceiras. A prática brasileira da cooperação sul-sul busca se diferenciar, em vários aspectos, da cooperação norte-sul, praticada pelos doadores tradicionais. Acerca desse assunto, julgue (C ou E) os itens seguir. Entende-se sistema urbano como um componente espacial do desenvolvimento social, o resultado de uma evolução histórica. A rede de cidades que o compõe, em | A cooperação sul-sul brasileira está calcada princípios da solidariedade e da não ingerência, o implica a não utilização dos mecanismos de cooperação para influenciar a política doméstica dos países com quais o Brasil coopera.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2023, 'Economia', NULL, 'Q23 Item 3 (TPS 2023): coordenadas pela Agência Brasileira de Cooperação (ABC) e implementadas com a colaboração de vários órgãos federais e organizações parceiras. A prática brasileira da cooperação sul-sul busca se diferenciar, em vários aspectos, da cooperação norte-sul, praticada pelos doadores tradicionais. Acerca desse assunto, julgue (C ou E) os itens seguir. Entende-se sistema urbano como um componente espacial do desenvolvimento social, o resultado de uma evolução histórica. A rede de cidades que o compõe, em | O Brasil segue o modelo de cooperação para desenvolvimento da OCDE e depende da contratação consultores para a implementação de projetos cooperação sul-sul.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2023, 'Economia', NULL, 'Q23 Item 4 (TPS 2023): coordenadas pela Agência Brasileira de Cooperação (ABC) e implementadas com a colaboração de vários órgãos federais e organizações parceiras. A prática brasileira da cooperação sul-sul busca se diferenciar, em vários aspectos, da cooperação norte-sul, praticada pelos doadores tradicionais. Acerca desse assunto, julgue (C ou E) os itens seguir. Entende-se sistema urbano como um componente espacial do desenvolvimento social, o resultado de uma evolução histórica. A rede de cidades que o compõe, em | A prática da cooperação sul-sul brasileira ocorre predominantemente pela oferta de cooperação financeira e pela construção de obras de infraestrutura. Área Livre PROVA que nos em de de os o Adivisão regionais dessa articula território subsistemas sistema processo pelo cidades, expansão Considerando inicial sistema 1 2 agencia/images/stories/PDFs/boletim_regional/170531bru16_ensaio07.pdf>. escala PMOURA, Na uma aceleração econômico Até povoamento inserção. sul-americana.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2023, 'Economia', NULL, 'Q29 Item 1 (TPS 2023): A respeito do Direito Internacional dos Direitos Humanos e do ordenamento jurídico brasileiro, julgue (C ou E) os itens a seguir. | De acordo com a Declaração e Programa de Ação de Viena de 1993, todos os direitos humanos são universais, indivisíveis, interdependentes e inter-relacionados.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2023, 'Economia', NULL, 'Q29 Item 2 (TPS 2023): A respeito do Direito Internacional dos Direitos Humanos e do ordenamento jurídico brasileiro, julgue (C ou E) os itens a seguir. | Segundo a Convenção Contra a Tortura e Outros Tratamentos ou Penas Cruéis, Desumanos ou Degradantes, de 1984, em nenhum caso podem ser invocadas circunstâncias excepcionais, como ameaça ou estado de guerra, instabilidade política interna ou qualquer outra emergência política, como justificativa para tortura.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2023, 'Economia', NULL, 'Q29 Item 3 (TPS 2023): A respeito do Direito Internacional dos Direitos Humanos e do ordenamento jurídico brasileiro, julgue (C ou E) os itens a seguir. | Embora em 2023 o Brasil não seja membro do Conselho de Direitos Humanos das Nações Unidas, as resoluções adotadas pelo referido órgão são vinculantes para o País.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2023, 'Economia', NULL, 'Q29 Item 4 (TPS 2023): A respeito do Direito Internacional dos Direitos Humanos e do ordenamento jurídico brasileiro, julgue (C ou E) os itens a seguir. | A Convenção Internacional sobre os Direitos das Pessoas com Deficiência e a Convenção Interamericana contra o Racismo, a Discriminação Racial e Formas Correlatas de Intolerância são equivalentes às emendas constitucionais, conforme o disposto no art. 5o, § 3o, da Constituição Federal de 1988, uma vez que foram aprovadas, em cada Casa do Congresso Nacional, em dois turnos, por três quintos dos votos dos respectivos membros.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2023, 'Economia', NULL, 'Q30 Item 1 (TPS 2023): O território, elemento constitutivo dos estados, conforme plasmado na Convenção de Montevidéu sobre Direitos e Deveres dos Estados, de 1933, é a dimensão física do Estado. Acerca desse tema, julgue (C ou E) os itens a seguir. | O princípio de uti possidetis iuris, inspirado no direito romano e utilizado no contexto da independência dos países latino-americanos da colonização espanhola, estabelece que os países recém-independentes mantenham as fronteiras à época da ocupação colonial. Esse princípio, contudo, não foi adotado em outros contextos de descolonização, sendo, inclusive, rechaçado em decisões da Corte Internacional de Justiça que trataram de questões fronteiriças entre países africanos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2023, 'Economia', NULL, 'Q30 Item 2 (TPS 2023): O território, elemento constitutivo dos estados, conforme plasmado na Convenção de Montevidéu sobre Direitos e Deveres dos Estados, de 1933, é a dimensão física do Estado. Acerca desse tema, julgue (C ou E) os itens a seguir. | A arbitragem entre os Países Baixos e os Estados Unidos da América, no caso “Ilha de Palmas”, validou a posição neerlandesa e afirmou o princípio da ocupação efetiva para que um Estado detenha soberania sobre determinado território.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2023, 'Economia', NULL, 'Q30 Item 3 (TPS 2023): O território, elemento constitutivo dos estados, conforme plasmado na Convenção de Montevidéu sobre Direitos e Deveres dos Estados, de 1933, é a dimensão física do Estado. Acerca desse tema, julgue (C ou E) os itens a seguir. | A doutrina Stimson, que leva o nome do secretário de Estado norte-americano Henry Stimson, em resposta à invasão japonesa da Manchúria, consagrou o princípio de que aquisições de território por um Estado agressor mediante guerra de conquista não seriam reconhecidas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2023, 'Economia', NULL, 'Q30 Item 4 (TPS 2023): O território, elemento constitutivo dos estados, conforme plasmado na Convenção de Montevidéu sobre Direitos e Deveres dos Estados, de 1933, é a dimensão física do Estado. Acerca desse tema, julgue (C ou E) os itens a seguir. | A Convenção de Viena sobre Sucessão de Estados, da qual o Brasil faz parte, prescreve a manutenção das fronteiras e os regimes fronteiriços estabelecidos em tratados firmados entre o Estado predecessor e o Estado sucessor.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2023, 'Economia', NULL, 'Q31 Item 1 (TPS 2023): A cooperação jurídica internacional é elemento essencial na efetividade de atos judiciais para além das fronteiras dos Estados. O Código de Processo Civil de 2015 inovou ao sistematizar a cooperação jurídica internacional com base nos direitos fundamentais garantidos na Constituição Federal. No que se refere ao instituto da cooperação jurídica internacional, julgue (C ou E) os itens a seguir. | O auxílio direto é medida de cooperação jurídica PROVA A2 3 4 QUESTÃO Pinternacional, de a diretamente designação Ministério De Civis autoridade da retida ou no A Superior homologar cartas Federal delibação Entre (MERCOSUL), sentenças via Central, processos Estado informações da acordo criança Emenda de Lhá retenção os rogatórias, do carta (STF). facilitando 32 menos países-membros em estrangeiras onde Tribunal das com central sentenças Sequestro que específica, administrativos ICnenhum rogatória Constitucional via que Relações Assim, indevidas a relacionadas a de tenha o ', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2023, 'Economia', NULL, 'Q31 Item 2 (TPS 2023): A cooperação jurídica internacional é elemento essencial na efetividade de atos judiciais para além das fronteiras dos Estados. O Código de Processo Civil de 2015 inovou ao sistematizar a cooperação jurídica internacional com base nos direitos fundamentais garantidos na Constituição Federal. No que se refere ao instituto da cooperação jurídica internacional, julgue (C ou E) os itens a seguir. | O Serviço Exterior Brasileiro é composto tão somente pela carreira de diplomata e pela carreira de oficial de chancelaria.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2023, 'Economia', NULL, 'Q31 Item 3 (TPS 2023): A cooperação jurídica internacional é elemento essencial na efetividade de atos judiciais para além das fronteiras dos Estados. O Código de Processo Civil de 2015 inovou ao sistematizar a cooperação jurídica internacional com base nos direitos fundamentais garantidos na Constituição Federal. No que se refere ao instituto da cooperação jurídica internacional, julgue (C ou E) os itens a seguir. | Os chefes de missão diplomática permanente serão escolhidos, sem exceção, entre os ministros de primeira classe ou os ministros de segunda classe.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2023, 'Economia', NULL, 'Q31 Item 4 (TPS 2023): A cooperação jurídica internacional é elemento essencial na efetividade de atos judiciais para além das fronteiras dos Estados. O Código de Processo Civil de 2015 inovou ao sistematizar a cooperação jurídica internacional com base nos direitos fundamentais garantidos na Constituição Federal. No que se refere ao instituto da cooperação jurídica internacional, julgue (C ou E) os itens a seguir. | Os chefes de missão diplomática permanente e de missão ou delegação permanente em organismo internacional serão nomeados pelo presidente da República com o título de embaixador, mediante aprovação prévia do Congresso Nacional. Área Livre CONCURSO PÚBLICO TERCEIRO‐SECRETÁRIO DA CARREIRA DE DIPLOMATA TIPO “A” – MANHÃ PÁGINA 14/15 QUESTÃO QUESTÃO 33 35 No que tange à sistemática do controle de Com relação aos tribunais internacionais e ao Direito constitucionalidade no sistema jurídico brasileiro, julgue Internacional do Meio Ambiente, julgue (C ou E) os itens (C ou E) os ite', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2023, 'Economia', NULL, 'Q36 Item 1 (TPS 2023): As far as comprehension of the text above is concerned, mark the statements below as right (C) or wrong (E). | The new meritocratic aristocracy’s distinguishing features are distancing or remoteness and a lack of moral and social responsibility.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2023, 'Economia', NULL, 'Q36 Item 2 (TPS 2023): As far as comprehension of the text above is concerned, mark the statements below as right (C) or wrong (E). | Meritocratic aristocracy is a mere construct, a contradiction in terms and therefore does not exist.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
